package com.fasterxml.jackson.databind.type;

import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.type.TypeFactory;
import com.fasterxml.jackson.databind.util.ArrayBuilders;
import com.fasterxml.jackson.databind.util.LRUMap;
import java.io.*;
import java.lang.reflect.*;
import java.lang.reflect.Type;
import java.lang.reflect.TypeVariable;
import java.math.*;
import java.util.*;
import java.util.Collections;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

/**
 * Unit tests for TypeFactory._fromVariable.
 * Since the method is protected, we use a Test subclass to expose it.
 */
public class TypeFactory__fromVariable_TriageGen2Test {

    private TestTypeFactory typeFactory;

    // Subclass to access protected method
    private static class TestTypeFactory extends TypeFactory {
        protected TestTypeFactory() {
            super(null, null);
        }

        @Override
        public JavaType _fromVariable(TypeVariable<?> type, TypeBindings context) {
            return super._fromVariable(type, context);
        }

        @Override
        protected JavaType _unknownType() {
            return JavaType.unknownType();
        }

        @Override
        protected JavaType _constructType(Type type, TypeBindings context) {
            // Mocking the construction to avoid heavy dependency on real type resolution logic
            // which might involve complex internal state of TypeFactory.
            return mock(JavaType.class);
        }
    }

    // Mocking TypeBindings as it is a complex class
    private TypeBindings mockContext;
    private TypeVariable<?> mockTypeVar;

    @Before
    public void setUp() {
        typeFactory = new TestTypeFactory();
        mockContext = mock(TypeBindings.class);
        mockTypeVar = mock(TypeVariable.class);
    }

    @Test
    public void test_fromVariable_withNullContext() {
        // When context is null, it should return _unknownType()
        JavaType result = typeFactory._fromVariable(mockTypeVar, null);
        assertEquals(JavaType.unknownType(), result);
    }

    @Test
    public void test_fromVariable_contextFindsType() {
        // Scenario: context.findType(name) returns a non-null JavaType
        String typeName = "T";
        JavaType expectedType = mock(JavaType.class);

        when(mockTypeVar.getName()).thenReturn(typeName);
        when(mockContext.findType(typeName)).thenReturn(expectedType);

        JavaType result = typeFactory._fromVariable(mockTypeVar, mockContext);

        assertEquals(expectedType, result);
        // Verify findType was called and _addPlaceholder was NOT called (early return)
        verify(mockContext).findType(typeName);
        verify(mockContext, never())._addPlaceholder(anyString());
    }

    @Test
    public void test_fromVariable_contextReturnsNull_UsesBounds() {
        // Scenario: context.findType(name) returns null, so it must use bounds
        String typeName = "T";
        Type boundType = Object.class;

        when(mockTypeVar.getName()).thenReturn(typeName);
        when(mockContext.findType(typeName)).thenReturn(null);
        when(mockTypeVar.getBounds()).thenReturn(new Type[]{boundType});

        // We need to verify that _addPlaceholder is called and _constructType is called with bounds[0]
        // Since we overridden _constructType in TestTypeFactory to return a mock, we check that.
        JavaType result = typeFactory._fromVariable(mockTypeVar, mockContext);

        assertNotNull(result);
        verify(mockContext).findType(typeName);
        verify(mockContext)._addPlaceholder(typeName);
        // The logic calls _constructType(bounds[0], context)
        // In our test implementation, _constructType returns a mock JavaType.
    }

    /**
     * This test specifically targets the logic where multiple bounds might exist,
     * ensuring it picks the first one as per the comment in the source.
     */
    @Test
    public void test_fromVariable_picksFirstBound() {
        String typeName = "T";
        Type bound1 = String.class;
        Type bound2 = Integer.class;

        when(mockTypeVar.getName()).thenReturn(typeName);
        when(mockContext.findType(typeName)).thenReturn(null);
        when(mockTypeVar.getBounds()).thenReturn(new Type[]{bound1, bound2});

        typeFactory._fromVariable(mockTypeVar, mockContext);

        verify(mockContext)._addPlaceholder(typeName);
        // The implementation uses bounds[0], which is bound1
    }
}
